namespace TiffCraft {

  // TiffCraft version
  constexpr int MAJOR_VERSION = 0;
  constexpr int MINOR_VERSION = 2;
  constexpr int PATCH_VERSION = 0;

  std::string version() {
    return std::to_string(MAJOR_VERSION)
      + "." + std::to_string(MINOR_VERSION)
      + "." + std::to_string(PATCH_VERSION);
  }

  // TIFF known tags
  // ===============
  // The enum provides a list of known TIFF tags for easy access and display.
  // Those tags not included in this list can still be accessed by their
  // numerical value.
  enum class Tag : uint16_t {
    // Image File Directory (IFD) tags

  template <typename T>
  T readValue(std::istream& stream, bool mustSwap = false) {
    T value;
    readValue(stream, value, mustSwap);
    return value;
  }

  std::istream& readAt(
    std::istream& stream, std::streampos pos,
    std::byte* buffer, std::size_t size) {
    if (!stream) {
      throw std::runtime_error("Stream is not valid for reading");
    }
    struct SeekGuard {
      std::istream& stream;
      std::streampos oldPos;
      SeekGuard(std::istream& s, std::streampos p) : stream(s), oldPos(s.tellg()) {
        stream.seekg(p);
      }
      ~SeekGuard() {
        stream.seekg(oldPos);
      }
    } seekGuard(stream, pos);
    if (!stream) {
      throw std::runtime_error("Failed to seek to position in stream");
    }
    stream.read(reinterpret_cast<char*>(buffer), size);
    return stream;
  }

